#!/usr/bin/env python3
"""The README's CLI text comes from the binary (EMMA-SOUL Dx3 73d06ff8 item 6).

Two checks, both against the forge binary given with --forge:
1. The block between the forge-help markers is the verbatim `forge --help` output (trailing
   whitespace stripped). `--write` regenerates it; without it, any difference fails.
2. Every forge invocation in a bash/sh/console or bare code block names a real command, and every
   flag on it is listed by `forge <command> --help` (or by `forge --help` for global flags). An
   invocation is `forge` at the start of a command: the line start, after `&&`, `||`, `;` or `|`,
   or after a `--` that hands the rest of the line to another program (`codex mcp add forge --
   forge mcp`).

Usage: readme-cli.py --forge target/debug/forge [--readme README.md] [--write]
Exit 1 with one line per mismatch.
"""
import argparse
import os
import re
import subprocess
import sys

START = "<!-- forge-help:start (generated by .github/scripts/readme-cli.py --write; do not edit) -->"
END = "<!-- forge-help:end -->"


def run_help(forge, *args):
    # No colour, whatever the caller's environment says: CLICOLOR_FORCE=1 would put escape codes in.
    env = {k: v for k, v in os.environ.items() if k not in ("CLICOLOR_FORCE", "CLICOLOR")}
    env["NO_COLOR"] = "1"
    out = subprocess.run([forge, *args, "--help"], capture_output=True, text=True, check=True,
                         env=env).stdout
    return "\n".join(line.rstrip() for line in out.splitlines()).strip("\n")


def help_block(forge):
    return f"{START}\n```text\n$ forge --help\n{run_help(forge)}\n```\n{END}"


def commands(top_help):
    """Subcommand names from the Commands: section of `forge --help`."""
    names, inside = set(), False
    for line in top_help.splitlines():
        if line.strip() == "Commands:":
            inside = True
            continue
        if inside:
            m = re.match(r"^  ([a-z][a-z0-9-]*)\s", line + " ")
            if m:
                names.add(m.group(1))
            elif line and not line.startswith(" "):
                inside = False
    return names


def flags(help_text):
    return set(re.findall(r"(?<![\w-])(--[a-z0-9][a-z0-9-]*|-[a-zA-Z])\b", help_text))


SHELL_LANGS = ("", "bash", "sh", "shell", "console")


def code_lines(readme):
    """(line number, text, fence language) for lines inside ```bash / ```sh / ```console
    fences and bare fences, with ``` and ~~~ both fence markers. A line ending in a backslash
    is joined with the next one, as the shell does."""
    marker, scanned, held = None, False, None
    for n, line in enumerate(readme.splitlines(), 1):
        fence = re.match(r"^\s*(```+|~~~+)\s*(\w*)", line)
        if fence:
            if marker is None:
                marker, lang = fence.group(1), fence.group(2)
                scanned = lang in SHELL_LANGS
                held = None
                continue
            # Only the opener's marker closes a block: ``` inside a ~~~ block is content.
            if fence.group(1).startswith(marker[0]) and len(fence.group(1)) >= len(marker) and not fence.group(2):
                marker, scanned, held = None, False, None
                continue
        if not scanned:
            continue
        if held is not None:
            start, text = held
            text = text + " " + line.strip()
        else:
            start, text = n, line
        if text.rstrip().endswith("\\"):
            held = (start, text.rstrip()[:-1])
            continue
        held = None
        yield start, text, lang


def check_commands(readme, forge, top_help):
    errors, cmds, global_flags, cache = [], commands(top_help), flags(top_help), {}
    for n, line, lang in code_lines(readme):
        text = re.sub(r"^\s*\$\s*", "", line.split("#", 1)[0]).strip()
        for words in invocations(text):
            found = check_invocation(n, words, forge, cmds, global_flags, cache)
            if found and lang == "":
                # A bare fence is read as shell. Prose in one reads as a forge call.
                found = [e + "; if this fence holds prose, label it ```text" for e in found]
            errors += found
    return errors


ENV_ASSIGN = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*=")


def is_forge(word):
    return word == "forge" or word.endswith("/forge")


def runs_forge(words, i):
    """True when words[i] is the program the shell runs: first in the segment, or after only
    sudo/env and VAR=value assignments, or a bare `forge` after `--` (`codex mcp add forge --
    forge mcp`). A path after `--` is an argument (`cargo run --example x -- target/debug/forge`)."""
    if i > 0 and words[i - 1] == "--":
        return words[i] == "forge"
    return all(w in ("sudo", "env") or ENV_ASSIGN.match(w) for w in words[:i])


def invocations(text):
    """The word lists of each forge invocation on one shell line."""
    # $( and backticks start a nested command; a closing ) or backtick ends it.
    text = re.sub(r"\$\(|`", " ; ", text)
    for segment in re.split(r"\s*(?:&&|\|\||;|\|)\s*", text):
        words = [w.strip("\"'").rstrip(")").strip("\"'") for w in segment.split()]
        words = [w for w in words if w]
        for i, w in enumerate(words):
            if is_forge(w) and runs_forge(words, i) and len(words) > i + 1:
                yield ["forge"] + words[i + 1:]
                break


def check_invocation(n, words, forge, cmds, global_flags, cache):
    errors = []
    cmd = words[1]
    if cmd.startswith("-"):
        return errors
    if cmd not in cmds:
        errors.append(f"README.md:{n}: `forge {cmd}` is not a forge command (forge --help)")
        return errors
    if cmd not in cache:
        cache[cmd] = flags(run_help(forge, cmd))
    for w in words[2:]:
        flag = w.split("=", 1)[0]
        if re.fullmatch(r"--?[A-Za-z0-9][A-Za-z0-9-]*", flag) and flag not in cache[cmd] | global_flags:
            errors.append(f"README.md:{n}: `forge {cmd} {flag}` is not listed by `forge {cmd} --help`")
    return errors


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--forge", required=True)
    ap.add_argument("--readme", default="README.md")
    ap.add_argument("--write", action="store_true")
    a = ap.parse_args()
    with open(a.readme, encoding="utf-8", newline="") as f:
        readme = f.read()
    pattern = re.compile(re.escape(START) + r".*?" + re.escape(END), re.S)
    found = pattern.findall(readme)
    want = help_block(a.forge)
    errors = []
    if len(found) != 1:
        errors.append(f"{a.readme}: want exactly one forge-help block, found {len(found)}")
    elif a.write:
        readme = pattern.sub(lambda _: want, readme)
        with open(a.readme, "w", encoding="utf-8", newline="") as f:
            f.write(readme)
        print(f"readme-cli: wrote the forge --help block in {a.readme}")
    elif found[0] != want:
        errors.append(f"{a.readme}: the forge-help block differs from `forge --help`; run "
                      ".github/scripts/readme-cli.py --forge <forge> --write")
    errors += check_commands(readme, a.forge, run_help(a.forge))
    for e in errors:
        print(f"::error::{e}")
    print(f"readme-cli: {'FAIL' if errors else 'ok'} ({len(errors)} problem(s))")
    return 1 if errors else 0


if __name__ == "__main__":
    sys.exit(main())
